<?php elseif($selectedExamSet['mode']==='revision'):?><ol><?php foreach($selectedExamSet['questions'] as $question):?><li><h4><?=h($question['prompt'])?></h4><p><b>Suggested answer:</b> <?=h($question['suggested_answer'])?></p><p><b>Explanation:</b> <?=h($question['explanation'])?></p></li><?php endforeach;?></ol>
<?php else:?><?php if($selectedExamSet['mode']==='mock'):?><div class="notice ai-exam-timer" data-seconds="<?=(int)$examSecondsRemaining?>">Time remaining <strong id="ai-exam-countdown">--:--</strong></div><?php endif;?><form method="post" id="ai-exam-attempt-form" data-mode="<?=h($selectedExamSet["mode"])?>"><input type="hidden" name="csrf" value="<?=h(token())?>"><input type="hidden" name="action" value="submit_ai_exam_attempt"><input type="hidden" name="set_id" value="<?=(int)$selectedExamSet['id']?>"><?php foreach($selectedExamSet['questions'] as $idx=>$question):?><fieldset class="ai-exam-question" data-index="<?=$idx?>"><legend><b><?=($idx+1)?>. <?=h($question['prompt'])?></b> <span class="pill"><?=h(ucwords(str_replace('_',' ',$question['type'])))?> · <?=h($question['difficulty'])?></span></legend><?php if($question['type']==='multiple_choice'):?><?php foreach($question['options'] as $oi=>$option):?><label class="ai-exam-option"><input type="radio" name="answer[<?=$idx?>]" value="<?=$oi?>" required> <?=h($option)?></label><?php endforeach;?><?php elseif($question['type']==='true_false'):?><label><input type="radio" name="answer[<?=$idx?>]" value="True" required> True</label><label><input type="radio" name="answer[<?=$idx?>]" value="False" required> False</label><?php else:?><label>Your answer<textarea name="answer[<?=$idx?>]" rows="<?=$question['type']==='essay'||$question['type']==='case_study'?5:2?>" maxlength="3000" <?=$question['type']==='essay'||$question['type']==='case_study'?'':'required'?>></textarea></label><small><?=$question['type']==='oral'?'Answer aloud, then enter key points for self-review.':'Written responses are not automatically scored.'?></small><?php endif;?></fieldset><?php endforeach;?><button class="btn">Submit practice answers</button></form><?php endif;?></div><?php endif;?>
